def one(text, old, new):
    if text.count(old) != 1:
        raise ValueError(f'Expected one anchor, found {text.count(old)}: {old[:120]}')
    return text.replace(old,new,1)
def paragraph(text, prefix, replacement):
    pattern = re.compile(r'^'+re.escape(prefix)+r'[^\n]*(?:\n(?!\n)[^\n]*)*', re.M)
    text, n = pattern.subn(lambda _: replacement, text)
    if n != 1:
        raise ValueError(f'Expected one paragraph {prefix}, found {n}')
    return text
def append(path, rows):
    existing = path.read_bytes()
    ids = {json.loads(x)['id'] for x in existing.decode('utf-8').splitlines() if x.strip()}
    assert not any(row['id'] in ids for row in rows)
    with path.open('ab') as stream:
        if existing and not existing.endswith(b'\n'):
            stream.write(b'\n')
        for row in rows:
            stream.write((json.dumps(row,ensure_ascii=False)+'\n').encode('utf-8'))
    assert path.read_bytes().startswith(existing)

